#include "digitor/media.hpp"
#include "digitor/renderer.hpp"
#include "digitor/timeline.hpp"
#include <cassert>
void test_editor(){digitor::FrameCache<digitor::VideoFrame> cache(1);auto a=std::make_shared<digitor::VideoFrame>();cache.put(1,a);assert(cache.get(1)==a);cache.put(2,std::make_shared<digitor::VideoFrame>());assert(!cache.get(1));digitor::Timeline t;auto track=t.add_track("V1");auto x=t.add_clip(track,"a",0,10);auto y=t.add_clip(track,"b",10,10);assert(t.roll(x,y,2));assert(t.find(x)->duration==12&&t.find(y)->source_in==2);assert(t.slip(y,2));assert(t.set_keyframe(x,0,0)&&t.set_keyframe(x,10,10));assert(*t.value_at(x,5)==5);assert(t.undo()&&t.redo());assert(t.schedule(3).size()==1&&t.schedule(3)[0].source_frame==3);assert(t.gaps(track,25).back().end()==25);digitor::Timeline nested;nested.add_track("inside");nested.add_clip(0,"nested source",0,5);auto nested_id=t.add_nested(track,nested,20);assert(t.nested(nested_id)&&t.schedule(22).size()==1);int builds=0;digitor::SharedRenderer shared([&](auto&g,const auto&r,auto&out){++builds;auto target=g.create_transient(4);g.add_pass({"shared",{},{{target,digitor::ResourceState::shader_write}},[&](auto&e){e.dispatch([&]{out.pixels.resize(r.width*r.height);});}});});digitor::PreviewRenderer preview(shared);assert(preview.frame(3,2,2)->pixels.size()==4);assert(preview.frame(3,2,2)->pixels.size()==4&&builds==1);}
